def allComposite (xs : List Nat) : Bool := xs.all (fun n => decide (¬ Nat.Prime n))

def run113 : List Nat := (List.range 113).map (fun i => 492114 + i)

def check_witness : Bool :=
  decide (Nat.Prime 492113) &&
  decide (Nat.Prime 492227) &&
  allComposite run113 &&
  decide (run113.length = 113) &&
  decide (492227 - 492113 = 114)

